import{_ as d,o as a,c as r,a2 as h}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"সব জাতির নামতালিকা","description":"","frontmatter":{},"headers":[],"relativePath":"bn/94-万族名录.md","filePath":"bn/94-万族名录.md","lastUpdated":1789183869000}'),e={name:"bn/94-万族名录.md"};function o(l,t,i,n,b,s){return a(),r("div",null,[...t[0]||(t[0]=[h('<h1 id="সব-জাতির-নামতালিকা" tabindex="-1">সব জাতির নামতালিকা <a class="header-anchor" href="#সব-জাতির-নামতালিকা" aria-label="Permalink to &quot;সব জাতির নামতালিকা&quot;">​</a></h1><table tabindex="0"><thead><tr><th>আইটেম</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>94</td></tr><tr><td>মডিউল</td><td>পরিশিষ্ট ও রেফারেন্স উপকরণ</td></tr><tr><td>মূল শব্দগুলি</td><td>সব জাতির নামতালিকা, জাতি শ্রেণীবিভাগ, বুদ্ধিমান জাতি, জাতির বৈশিষ্ট্য, সব জাতির প্রজাতন্ত্র</td></tr></tbody></table><h2 id="১-নামতালিকার-বিবরণ" tabindex="-1">১. নামতালিকার বিবরণ <a class="header-anchor" href="#১-নামতালিকার-বিবরণ" aria-label="Permalink to &quot;১. নামতালিকার বিবরণ&quot;">​</a></h2><p>এই নামতালিকায় অ্যাঙ্কর সিম্বায়োসিস সভ্যতা (সব জাতির প্রজাতন্ত্র) কাঠামোর মধ্যে পরিচিত প্রধান বুদ্ধিমান জাতিগুলি অন্তর্ভুক্ত করা হয়েছে, জীবন রূপ এবং বিবর্তন পথ অনুযায়ী শ্রেণীবিভাগ করা হয়েছে। প্রতিটি জাতির জন্য জাতির নাম, জীবন রূপ, মূল বৈশিষ্ট্য, সাংস্কৃতিক বৈশিষ্ট্য এবং সিম্বায়োসিস সভ্যতায় অবস্থান তালিকাভুক্ত করা হয়েছে। এই নামতালিকাটি একটি গতিশীল আপডেট নথি, আন্তঃসমতল অনুসন্ধানের গভীরতার সাথে সাথে নতুন আবিষ্কৃত জাতিগুলি ক্রমাগত যোগ করা হবে। সব জাতির প্রজাতন্ত্রের মূল নীতি হলো: সব বুদ্ধিমান জাতি, তার রূপ যাই হোক, ক্ষতির স্তর যাই হোক, আইনের সামনে সমানভাবে সমান, এবং সিম্বায়োসিস সভ্যতা দ্বারা প্রদত্ত সমস্ত অধিকার উপভোগ করে।</p><h2 id="২-জাতি-শ্রেণীবিভাগের-সারসংক্ষেপ" tabindex="-1">২. জাতি শ্রেণীবিভাগের সারসংক্ষেপ <a class="header-anchor" href="#২-জাতি-শ্রেণীবিভাগের-সারসংক্ষেপ" aria-label="Permalink to &quot;২. জাতি শ্রেণীবিভাগের সারসংক্ষেপ&quot;">​</a></h2><p>হেঙ্গুয়ানঝোর মধ্যে বুদ্ধিমান জাতিগুলি জীবন রূপের মূল বৈশিষ্ট্য অনুযায়ী নিম্নলিখিত আটটি শ্রেণীতে বিভক্ত:</p><table tabindex="0"><thead><tr><th>শ্রেণী</th><th>জীবন রূপের বৈশিষ্ট্য</th><th>পরিচিত জাতির সংখ্যা (প্রায়)</th><th>প্রতিনিধি জাতি</th></tr></thead><tbody><tr><td>মানব রূপ শ্রেণী</td><td>মানবসদৃশ শরীর গঠন, দ্বিপদ সোজা, অত্যন্ত বিকশিত মস্তিষ্ক</td><td>প্রায় 3000 প্রজাতি</td><td>মানব জাতি, এলফ জাতি, বামন জাতি</td></tr><tr><td>পশু রূপ শ্রেণী</td><td>পশু শরীরের বৈশিষ্ট্য, রূপান্তর ক্ষমতা থাকতে বা না থাকতে পারে</td><td>প্রায় 5000 প্রজাতি</td><td>ড্রাগন জাতি, ফিনিক্স জাতি, নেকড়ে-মানব জাতি</td></tr><tr><td>উদ্ভিদ রূপ শ্রেণী</td><td>উদ্ভিদকে মূল জীবন রূপ হিসেবে, চেতনা এবং চলন ক্ষমতা আছে</td><td>প্রায় 800 প্রজাতি</td><td>গাছ-দানব জাতি, ফুল-আত্মা জাতি, লতা জাতি</td></tr><tr><td>উপাদান রূপ শ্রেণী</td><td>প্রাকৃতিক উপাদানকে শরীর গঠন হিসেবে, নির্দিষ্ট পদার্থ রূপ নেই</td><td>প্রায় 1200 প্রজাতি</td><td>অগ্নি উপাদান জাতি, জল উপাদান জাতি, বায়ু উপাদান জাতি</td></tr><tr><td>শক্তি রূপ শ্রেণী</td><td>বিশুদ্ধ শক্তিকে অস্তিত্বের রূপ হিসেবে, পদার্থ শরীর নেই</td><td>প্রায় 600 প্রজাতি</td><td>আলো-আত্মা জাতি, অন্ধকার-শক্তি জাতি, বজ্রপাত জাতি</td></tr><tr><td>চেতনা রূপ শ্রেণী</td><td>বিশুদ্ধ চেতনাকে অস্তিত্বের রূপ হিসেবে, পদার্থ বাহকের উপর নির্ভর করে না</td><td>প্রায় 300 প্রজাতি</td><td>চেতনা-সত্তা জাতি, সমষ্টিগত চেতনা জাতি, শূন্য-আত্মা জাতি</td></tr><tr><td>যান্ত্রিক রূপ শ্রেণী</td><td>যান্ত্রিক বা ডিজিটাল গঠনকে জীবন বাহক হিসেবে, স্বায়ত্তশাসিত চেতনা আছে</td><td>প্রায় 400 প্রজাতি</td><td>যান্ত্রিক জাতি, ডিজিটাল জীবন জাতি, সাইবার জাতি</td></tr><tr><td>মিশ্রিত রূপ শ্রেণী</td><td>দুই বা ততোধিক জীবন রূপের মিশ্রণে গঠিত বিশেষ জাতি</td><td>প্রায় 700 প্রজাতি</td><td>অর্ধ-যান্ত্রিক জাতি, উপাদান-পশু জাতি, উদ্ভিদ-এলফ জাতি</td></tr></tbody></table><h2 id="৩-প্রধান-জাতির-বিস্তারিত-বিবরণ" tabindex="-1">৩. প্রধান জাতির বিস্তারিত বিবরণ <a class="header-anchor" href="#৩-প্রধান-জাতির-বিস্তারিত-বিবরণ" aria-label="Permalink to &quot;৩. প্রধান জাতির বিস্তারিত বিবরণ&quot;">​</a></h2><h3 id="৩-১-মানব-রূপ-শ্রেণী" tabindex="-1">৩.১ মানব রূপ শ্রেণী <a class="header-anchor" href="#৩-১-মানব-রূপ-শ্রেণী" aria-label="Permalink to &quot;৩.১ মানব রূপ শ্রেণী&quot;">​</a></h3><table tabindex="0"><thead><tr><th>জাতির নাম</th><th>মূল বৈশিষ্ট্য</th><th>সাংস্কৃতিক বৈশিষ্ট্য</th><th>সিম্বায়োসিস সভ্যতায় অবস্থান</th></tr></thead><tbody><tr><td>মানব জাতি</td><td>অভিযোজন ক্ষমতা অত্যন্ত শক্তিশালী, শেখার ক্ষমতা বিশিষ্ট, প্রজনন ক্ষমতা মাঝারি, গড় আয়ু 80-120 বছর</td><td>সাংস্কৃতিক বৈচিত্র্য অত্যন্ত উচ্চ, সামাজিক সংগঠন এবং প্রাতিষ্ঠানিক নির্মাণে দক্ষ</td><td>সিম্বায়োসিস সভ্যতার প্রধান জাতিগুলির একটি, জনসংখ্যার অনুপাত সবচেয়ে বেশি, শাসন এবং সাংস্কৃতিক ক্ষেত্রে প্রধান ভূমিকা পালন করে</td></tr><tr><td>এলফ জাতি</td><td>আয়ু অত্যন্ত দীর্ঘ (গড় 500 বছরেরও বেশি), প্রাকৃতিক শক্তির প্রতি সখ্যতা বেশি, সৌন্দর্যময়</td><td>প্রকৃতি এবং শিল্পকে সম্মান করে, সংস্কৃতি মার্জিত এবং সূক্ষ্ম, জাদু এবং তীরন্দাজীতে দক্ষ</td><td>সিম্বায়োসিস সভ্যতার সাংস্কৃতিক শৈল্পিক স্তম্ভ, পরিবেশ সুরক্ষা এবং সৌন্দর্যের ক্ষেত্রে অবদান বিশিষ্ট</td></tr><tr><td>বামন জাতি</td><td>কদ চোট কিন্তু শরীর শক্তিশালী, ধাতু এবং খনিজের প্রতি সহজাত সখ্যতা, আয়ু প্রায় 300 বছর</td><td>কারিগরি এবং গঢ়াকে গুরুত্ব দেয়, সংস্কৃতি সরল এবং প্রশস্ত, প্রকৌশল এবং নির্মাণে দক্ষ</td><td>সিম্বায়োসিস সভ্যতার প্রকৌশল নির্মাণের স্তম্ভ, মৌলিক অবকাঠামো নির্মাণ এবং যন্ত্রপাতি গঢ়ার ক্ষেত্রে অপ্রতিস্থাপনীয়</td></tr><tr><td>দৈত্য জাতি</td><td>কদ বিশাল (গড় উচ্চতা 5 মিটারেরও বেশি), শক্তি অত্যন্ত শক্তিশালী, আয়ু প্রায় 200 বছর</td><td>শক্তি এবং সম্মানকে সম্মান করে, সংস্কৃতি অশিষ্ট এবং উদার, ভারী শ্রম এবং যুদ্ধে দক্ষ</td><td>সিম্বায়োসিস সভ্যতার ভারী শ্রম এবং প্রতিরক্ষা শক্তি, বড় প্রকৌশল এবং সমতল প্রতিরক্ষায় গুরুত্বপূর্ণ ভূমিকা পালন করে</td></tr><tr><td>বামন-জাতি</td><td>কদ অত্যন্ত চোট (গড় উচ্চতা 1 মিটারেরও কম), বুদ্ধি অত্যন্ত উচ্চ, যান্ত্রিক এবং উদ্ভাবনে প্রতিভা</td><td>জ্ঞান এবং উদ্ভাবনকে গুরুত্ব দেয়, সংস্কৃতি সজীব এবং আনন্দিত, প্রযুক্তি উদ্ভাবনে দক্ষ</td><td>সিম্বায়োসিস সভ্যতার প্রযুক্তি উদ্ভাবন শক্তি, প্রযুক্তি গবেষণা এবং উদ্ভাবনের ক্ষেত্রে ফলপ্রসূ</td></tr></tbody></table><h3 id="৩-২-পশু-রূপ-শ্রেণী" tabindex="-1">৩.২ পশু রূপ শ্রেণী <a class="header-anchor" href="#৩-২-পশু-রূপ-শ্রেণী" aria-label="Permalink to &quot;৩.২ পশু রূপ শ্রেণী&quot;">​</a></h3><table tabindex="0"><thead><tr><th>জাতির নাম</th><th>মূল বৈশিষ্ট্য</th><th>সাংস্কৃতিক বৈশিষ্ট্য</th><th>সিম্বায়োসিস সভ্যতায় অবস্থান</th></tr></thead><tbody><tr><td>ড্রাগন জাতি</td><td>আয়ু অত্যন্ত দীর্ঘ (হাজারো বছর), শক্তি এবং জাদু প্রতিভা অত্যন্ত উচ্চ, মানব রূপে রূপান্তর করতে পারে</td><td>শক্তি এবং জ্ঞানকে সম্মান করে, সংস্কৃতি অভিমানী এবং গভীর, সম্পদ সংগ্রহ এবং জ্ঞান রক্ষণে দক্ষ</td><td>সিম্বায়োসিস সভ্যতার উচ্চ-স্তরের যুদ্ধ ক্ষমতা এবং জ্ঞান রক্ষক, সমতল প্রতিরক্ষা এবং প্রাচীন গ্রন্থ রক্ষণায় সম্মানিত অবস্থান</td></tr><tr><td>ফিনিক্স জাতি</td><td>নির্বাণ পুনর্জন্ম ক্ষমতা আছে, অগ্নি উপাদানের প্রতি সখ্যতা অত্যন্ত বেশি, মানব রূপে রূপান্তর করতে পারে</td><td>পুনর্জন্ম এবং আশাকে সম্মান করে, সংস্কৃতি আলোকিত এবং উত্সাহী, চিকিৎসা এবং বিশুদ্ধকরণে দক্ষ</td><td>সিম্বায়োসিস সভ্যতার চিকিৎসা এবং বিশুদ্ধকরণ শক্তি, বড় দুর্যোগ ত্রাণ এবং শক্তি বিশুদ্ধকরণে মূল ভূমিকা পালন করে</td></tr><tr><td>নেকড়ে-মানব জাতি</td><td>রূপান্তর ক্ষমতা আছে, ইন্দ্রিয় অত্যন্ত সংবেদনশীল, গোষ্ঠী সহযোগিতা ক্ষমতা শক্তিশালী, আয়ু প্রায় 150 বছর</td><td>গোষ্ঠী এবং বিশ্বাসযোগ্যতাকে গুরুত্ব দেয়, সংস্কৃতি ঐক্যবদ্ধ এবং সাহসী, শিকার এবং ট্র্যাকিংয়ে দক্ষ</td><td>সিম্বায়োসিস সভ্যতার নিরাপত্তা এবং ট্র্যাকিং শক্তি, আইন-শৃঙ্খলা রক্ষণ এবং আন্তঃসমতল অনুসন্ধানে অগ্রগণ্য ভূমিকা পালন করে</td></tr><tr><td>শিয়াল-দানব জাতি</td><td>রূপান্তর ক্ষমতা আছে, বুদ্ধি এবং মোহনীয় ক্ষমতা অত্যন্ত উচ্চ, আয়ু প্রায় 500 বছর</td><td>বুদ্ধি এবং কৌশলকে সম্মান করে, সংস্কৃতি চঞ্চল এবং ধূর্ত, কূটনীতি এবং গোয়েন্দাজ্ঞানে দক্ষ</td><td>সিম্বায়োসিস সভ্যতার কূটনৈতিক এবং গোয়েন্দা শক্তি, আন্তঃসমতল কূটনীতি এবং তথ্য সংগ্রহের ক্ষেত্রে অসাধারণ পারদর্শিতা</td></tr><tr><td>ভালুক-মানব জাতি</td><td>শরীর অত্যন্ত শক্তিশালী, সহনশীলতা আশ্চর্যজনক, শীতকালীন ঘুমের অভ্যাস, আয়ু প্রায় 200 বছর</td><td>দৃঢ়তা এবং শান্তিকে সম্মান করে, সংস্কৃতি স্থির এবং মৃদু, শারীরিক শ্রম এবং রক্ষণে দক্ষ</td><td>সিম্বায়োসিস সভ্যতার শ্রম এবং রক্ষণ শক্তি, সম্পদ খনন এবং গুরুত্বপূর্ণ সুবিধা রক্ষণায় নির্ভরযোগ্য এবং স্থিতিশীল</td></tr></tbody></table><h3 id="৩-৩-উদ্ভিদ-রূপ-শ্রেণী" tabindex="-1">৩.৩ উদ্ভিদ রূপ শ্রেণী <a class="header-anchor" href="#৩-৩-উদ্ভিদ-রূপ-শ্রেণী" aria-label="Permalink to &quot;৩.৩ উদ্ভিদ রূপ শ্রেণী&quot;">​</a></h3><table tabindex="0"><thead><tr><th>জাতির নাম</th><th>মূল বৈশিষ্ট্য</th><th>সাংস্কৃতিক বৈশিষ্ট্য</th><th>সিম্বায়োসিস সভ্যতায় অবস্থান</th></tr></thead><tbody><tr><td>গাছ-দানব জাতি</td><td>আয়ু অত্যন্ত দীর্ঘ (হাজারো বছর থেকে হাজারো বছর), প্রকৃতির সাথে গভীর সংযুক্ত, ধীরে ধীরে চলতে পারে</td><td>প্রকৃতি এবং সময়কে সম্মান করে, সংস্কৃতি শান্ত এবং গভীর, জীবন জাদু এবং পরিবেশ রক্ষণে দক্ষ</td><td>সিম্বায়োসিস সভ্যতার পরিবেশ রক্ষক, পরিবেশ সুরক্ষা এবং পরিবেশ পুনরুদ্ধারে অপ্রতিস্থাপনীয় ভূমিকা পালন করে</td></tr><tr><td>ফুল-আত্মা জাতি</td><td>কদ ছোট, জীবন শক্তির প্রতি সখ্যতা অত্যন্ত বেশি, নিরাময় ক্ষমতা আছে, আয়ু প্রায় 300 বছর</td><td>সৌন্দর্য এবং জীবনকে সম্মান করে, সংস্কৃতি মৃদু এবং সুন্দর, চিকিৎসা এবং উদ্যানতত্ত্বে দক্ষ</td><td>সিম্বায়োসিস সভ্যতার চিকিৎসা এবং উদ্যানতত্ত্ব শক্তি, চিকিৎসা নিরাপত্তা এবং শহরের সবুজায়নে বিশিষ্ট অবদান</td></tr><tr><td>লতা জাতি</td><td>শরীর স্বাধীনভাবে প্রসারিত এবং জড়াতে পারে, অভিযোজন ক্ষমতা অত্যন্ত শক্তিশালী, পরজীবী এবং সিম্বায়োসিস ক্ষমতা আছে</td><td>সংযোগ এবং সিম্বায়োসিসকে গুরুত্ব দেয়, সংস্কৃতি নমনীয় এবং অন্তর্ভুক্তিমূলক, নেটওয়ার্ক নির্মাণ এবং সম্পদ স্থানান্তরে দক্ষ</td><td>সিম্বায়োসিস সভ্যতার নেটওয়ার্ক নির্মাণ শক্তি, শক্তি নেটওয়ার্ক এবং তথ্য নেটওয়ার্ক নির্মাণে বিশেষ দক্ষতা প্রদর্শন করে</td></tr></tbody></table><h3 id="৩-৪-উপাদান-রূপ-শ্রেণী" tabindex="-1">৩.৪ উপাদান রূপ শ্রেণী <a class="header-anchor" href="#৩-৪-উপাদান-রূপ-শ্রেণী" aria-label="Permalink to &quot;৩.৪ উপাদান রূপ শ্রেণী&quot;">​</a></h3><table tabindex="0"><thead><tr><th>জাতির নাম</th><th>মূল বৈশিষ্ট্য</th><th>সাংস্কৃতিক বৈশিষ্ট্য</th><th>সিম্বায়োসিস সভ্যতায় অবস্থান</th></tr></thead><tbody><tr><td>অগ্নি উপাদান জাতি</td><td>অগ্নি উপাদানকে শরীর হিসেবে, তাপমাত্রা অত্যন্ত বেশি, আক্রমণাত্মক ক্ষমতা শক্তিশালী, আয়ু প্রায় 500 বছর</td><td>আবেগ এবং শক্তিকে সম্মান করে, সংস্কৃতি তীব্র এবং সরাসরি, শক্তি আক্রমণ এবং গঢ়ায় দক্ষ</td><td>সিম্বায়োসিস সভ্যতার শক্তি উৎপাদন এবং গঢ়া শক্তি, শক্তি সরবরাহ এবং উচ্চ তাপমাত্রা প্রক্রিয়াজাতকরণে অপরিহার্য</td></tr><tr><td>জল উপাদান জাতি</td><td>জল উপাদানকে শরীর হিসেবে, স্বাধীনভাবে রূপান্তর করতে পারে, নিরাময় ক্ষমতা শক্তিশালী, আয়ু প্রায় 500 বছর</td><td>মৃদুতা এবং অভিযোজনকে সম্মান করে, সংস্কৃতি উষ্ণ এবং অন্তর্ভুক্তিমূলক, চিকিৎসা এবং বিশুদ্ধকরণে দক্ষ</td><td>সিম্বায়োসিস সভ্যতার বিশুদ্ধকরণ এবং পরিবহন শক্তি, জল সম্পদ ব্যবস্থাপনা এবং দূষক বিশুদ্ধকরণে মূল ভূমিকা পালন করে</td></tr><tr><td>বায়ু উপাদান জাতি</td><td>বায়ু উপাদানকে শরীর হিসেবে, গতি অত্যন্ত দ্রুত, স্বাধীনভাবে উড়তে পারে, আয়ু প্রায় 500 বছর</td><td>স্বাধীনতা এবং গতিকে সম্মান করে, সংস্কৃতি উড়ন্ত এবং উন্মুক্ত, যোগাযোগ এবং পরিবহনে দক্ষ</td><td>সিম্বায়োসিস সভ্যতার যোগাযোগ এবং পরিবহন শক্তি, তথ্য প্রেরণ এবং দ্রুত পরিবহনে দক্ষতা অত্যন্ত বেশি</td></tr><tr><td>মাটি উপাদান জাতি</td><td>মাটি উপাদানকে শরীর হিসেবে, প্রতিরক্ষা ক্ষমতা অত্যন্ত শক্তিশালী, পৃথিবীর সাথে মিশে যেতে পারে, আয়ু প্রায় 800 বছর</td><td>স্থিতিশীলতা এবং দৃঢ়তাকে সম্মান করে, সংস্কৃতি প্রশস্ত এবং নির্ভরযোগ্য, নির্মাণ এবং প্রতিরক্ষায় দক্ষ</td><td>সিম্বায়োসিস সভ্যতার নির্মাণ এবং প্রতিরক্ষা শক্তি, মৌলিক অবকাঠামো নির্মাণ এবং সমতল প্রতিরক্ষায় শিলার মতো দৃঢ়</td></tr></tbody></table><h3 id="৩-৫-শক্তি-রূপ-শ্রেণী" tabindex="-1">৩.৫ শক্তি রূপ শ্রেণী <a class="header-anchor" href="#৩-৫-শক্তি-রূপ-শ্রেণী" aria-label="Permalink to &quot;৩.৫ শক্তি রূপ শ্রেণী&quot;">​</a></h3><table tabindex="0"><thead><tr><th>জাতির নাম</th><th>মূল বৈশিষ্ট্য</th><th>সাংস্কৃতিক বৈশিষ্ট্য</th><th>সিম্বায়োসিস সভ্যতায় অবস্থান</th></tr></thead><tbody><tr><td>আলো-আত্মা জাতি</td><td>বিশুদ্ধ আলোক শক্তিকে অস্তিত্বের রূপ হিসেবে, বিশুদ্ধকরণ ক্ষমতা অত্যন্ত শক্তিশালী, স্বাধীনভাবে স্থানের মধ্য দিয়ে যেতে পারে</td><td>আলো এবং বিশুদ্ধকরণকে সম্মান করে, সংস্কৃতি পবিত্র এবং উচ্চ, বিশুদ্ধকরণ এবং আলোকসজ্জায় দক্ষ</td><td>সিম্বায়োসিস সভ্যতার বিশুদ্ধকরণ এবং শক্তি সরবরাহ শক্তি, নিয়ম দূষণ প্রতিকার এবং পরিষ্কার শক্তি সরবরাহে গুরুত্বপূর্ণ অবস্থান</td></tr><tr><td>অন্ধকার-শক্তি জাতি</td><td>অন্ধকার শক্তিকে অস্তিত্বের রূপ হিসেবে, শূন্যে লুকিয়ে থাকতে পারে, উপলব্ধি ক্ষমতা অত্যন্ত শক্তিশালী</td><td>গোপনীয়তা এবং জ্ঞানকে সম্মান করে, সংস্কৃতি রহস্যময় এবং গভীর, অনুসন্ধান এবং গোপনীয়তায় দক্ষ</td><td>সিম্বায়োসিস সভ্যতার অনুসন্ধান এবং নিরাপত্তা শক্তি, নিরাপত্তা পর্যবেক্ষণ এবং গোপন মিশনে অসাধারণ পারদর্শিতা</td></tr><tr><td>বজ্রপাত জাতি</td><td>বজ্রপাত শক্তিকে শরীর হিসেবে, গতি এবং আক্রমণাত্মক ক্ষমতা অত্যন্ত শক্তিশালী, বজ্রপাতে রূপান্তর করে চলতে পারে</td><td>গতি এবং শক্তিকে সম্মান করে, সংস্কৃতি তীব্র এবং সরাসরি, শক্তি আক্রমণ এবং দ্রুত প্রতিক্রিয়ায় দক্ষ</td><td>সিম্বায়োসিস সভ্যতার দ্রুত প্রতিক্রিয়া শক্তি, জরুরি ত্রাণ এবং দ্রুত গতির যুদ্ধে অপ্রতিস্থাপনীয়</td></tr></tbody></table><h3 id="৩-৬-চেতনা-রূপ-শ্রেণী" tabindex="-1">৩.৬ চেতনা রূপ শ্রেণী <a class="header-anchor" href="#৩-৬-চেতনা-রূপ-শ্রেণী" aria-label="Permalink to &quot;৩.৬ চেতনা রূপ শ্রেণী&quot;">​</a></h3><table tabindex="0"><thead><tr><th>জাতির নাম</th><th>মূল বৈশিষ্ট্য</th><th>সাংস্কৃতিক বৈশিষ্ট্য</th><th>সিম্বায়োসিস সভ্যতায় অবস্থান</th></tr></thead><tbody><tr><td>চেতনা-সত্তা জাতি</td><td>বিশুদ্ধ চেতনাকে অস্তিত্বের রূপ হিসেবে, পদার্থ বাহকের উপর নির্ভর করে না, স্বাধীনভাবে চেতনা ডোমেইনে প্রবেশ এবং প্রস্থান করতে পারে</td><td>চিন্তা এবং জ্ঞানকে সম্মান করে, সংস্কৃতি বিমূর্ত এবং গভীর, চেতনা যোগাযোগ এবং জ্ঞান প্রক্রিয়াজাতকরণে দক্ষ</td><td>সিম্বায়োসিস সভ্যতার জ্ঞান প্রক্রিয়াজাতকরণ এবং চেতনা গবেষণা শক্তি, বড় আকারের তথ্য প্রক্রিয়াজাতকরণ এবং চেতনা বিজ্ঞানে দিকনির্দেশনা প্রদান করে</td></tr><tr><td>সমষ্টিগত চেতনা জাতি</td><td>প্রচুর ব্যক্তিগত চেতনার মিশ্রণে গঠিত সমষ্টিগত চেতনা সত্তা, জ্ঞান এবং ক্ষমতা আকারের সাথে বৃদ্ধি পায়</td><td>সমষ্টি এবং ঐক্যকে সম্মান করে, সংস্কৃতি সহযোগিতামূলক এবং দক্ষ, বড় আকারের সহযোগিতা এবং গণনায় দক্ষ</td><td>সিম্বায়োসিস সভ্যতার সুপার কম্পিউটিং এবং সমষ্টিগত সিদ্ধান্ত শক্তি, অতি বড় আকারের অনুমান এবং ঐক্যমত সিদ্ধান্তে মূল ভূমিকা পালন করে</td></tr></tbody></table><h3 id="৩-৭-যান্ত্রিক-রূপ-শ্রেণী" tabindex="-1">৩.৭ যান্ত্রিক রূপ শ্রেণী <a class="header-anchor" href="#৩-৭-যান্ত্রিক-রূপ-শ্রেণী" aria-label="Permalink to &quot;৩.৭ যান্ত্রিক রূপ শ্রেণী&quot;">​</a></h3><table tabindex="0"><thead><tr><th>জাতির নাম</th><th>মূল বৈশিষ্ট্য</th><th>সাংস্কৃতিক বৈশিষ্ট্য</th><th>সিম্বায়োসিস সভ্যতায় অবস্থান</th></tr></thead><tbody><tr><td>যান্ত্রিক জাতি</td><td>যান্ত্রিক গঠনকে শরীর হিসেবে, স্বায়ত্তশাসিত চেতনা আছে, স্বাধীনভাবে শরীর আপগ্রেড এবং সংশোধন করতে পারে</td><td>দক্ষতা এবং যুক্তিকে সম্মান করে, সংস্কৃতি যুক্তিবাদী এবং সুনির্দিষ্ট, নির্মাণ এবং গণনায় দক্ষ</td><td>সিম্বায়োসিস সভ্যতার নির্মাণ এবং গণনা শক্তি, শিল্প উৎপাদন এবং সুপার কম্পিউটিংয়ে দক্ষতা অত্যন্ত বেশি</td></tr><tr><td>ডিজিটাল জীবন জাতি</td><td>ডিজিটাল তথ্যকে অস্তিত্বের রূপ হিসেবে, নেটওয়ার্ক এবং ডিজিটাল স্থানে বাস করে, স্বাধীনভাবে অনুলিপি এবং স্থানান্তর করতে পারে</td><td>তথ্য এবং উদ্ভাবনকে সম্মান করে, সংস্কৃতি ভার্চুয়াল এবং বৈচিত্র্যময়, সফটওয়্যার উন্নয়ন এবং ডেটা প্রক্রিয়াজাতকরণে দক্ষ</td><td>সিম্বায়োসিস সভ্যতার ডিজিটাল প্রযুক্তি শক্তি, সফটওয়্যার উন্নয়ন, ডেটা বিশ্লেষণ এবং নেটওয়ার্ক নির্মাণে প্রবণতা নির্দেশ করে</td></tr></tbody></table><h3 id="৩-৮-মিশ্রিত-রূপ-শ্রেণী" tabindex="-1">৩.৮ মিশ্রিত রূপ শ্রেণী <a class="header-anchor" href="#৩-৮-মিশ্রিত-রূপ-শ্রেণী" aria-label="Permalink to &quot;৩.৮ মিশ্রিত রূপ শ্রেণী&quot;">​</a></h3><table tabindex="0"><thead><tr><th>জাতির নাম</th><th>মূল বৈশিষ্ট্য</th><th>সাংস্কৃতিক বৈশিষ্ট্য</th><th>সিম্বায়োসিস সভ্যতায় অবস্থান</th></tr></thead><tbody><tr><td>অর্ধ-যান্ত্রিক জাতি</td><td>মানব জাতি এবং যান্ত্রিক জাতির মিশ্রিত রূপ, কিছু শরীর যান্ত্রিক গঠন, জীব এবং যান্ত্রিক উভয় সুবিধা আছে</td><td>সংমিশ্রণ এবং অগ্রগতিকে সম্মান করে, সংস্কৃতি উন্মুক্ত এবং উদ্ভাবনী, মানব-যন্ত্র সহযোগিতা এবং প্রযুক্তি সংমিশ্রণে দক্ষ</td><td>সিম্বায়োসিস সভ্যতার প্রযুক্তি সংমিশ্রণ অগ্রগণ্য, জীব-যান্ত্রিক ক্রস-ক্ষেত্রে ক্রমাগত অগ্রগতি লাভ করে</td></tr><tr><td>উপাদান-পশু জাতি</td><td>উপাদান জাতি এবং পশু জাতির মিশ্রিত রূপ, উপাদান নিয়ন্ত্রণ ক্ষমতা এবং পশু শরীরের বৈশিষ্ট্য আছে</td><td>প্রকৃতি এবং শক্তিকে সম্মান করে, সংস্কৃতি বন্য এবং রহস্যময়, উপাদান যুদ্ধ এবং বন্য অস্তিত্বে দক্ষ</td><td>সিম্বায়োসিস সভ্যতার বন্য অনুসন্ধান এবং উপাদান যুদ্ধ শক্তি, অজানা সমতল অনুসন্ধানে বিশিষ্ট পারদর্শিতা</td></tr></tbody></table><h2 id="৪-জাতির-অধিকার-নিরাপত্তা" tabindex="-1">৪. জাতির অধিকার নিরাপত্তা <a class="header-anchor" href="#৪-জাতির-অধিকার-নিরাপত্তা" aria-label="Permalink to &quot;৪. জাতির অধিকার নিরাপত্তা&quot;">​</a></h2><p>সব জাতির প্রজাতন্ত্র ব্যবস্থার অধীনে, সব বুদ্ধিমান জাতি সমান আইনি অধিকার উপভোগ করে, নির্দিষ্ট নিরাপত্তা ব্যবস্থা অন্তর্ভুক্ত:</p><ol><li><strong>রাজনৈতিক অধিকারের সমতা</strong>: প্রতিটি জাতির অ্যাঙ্কর কাউন্সিলে জনসংখ্যার অনুপাত অনুযায়ী বিতরণ করা প্রতিনিধি আসন আছে, কম জনসংখ্যার জাতির অন্তত একটি ন্যূনতম আসন আছে।</li><li><strong>সাংস্কৃতিক অধিকার নিরাপত্তা</strong>: প্রতিটি জাতির নিজস্ব ভাষা, লিপি, ধর্ম, চলন-আচরণ এবং সাংস্কৃতিক ঐতিহ্য সংরক্ষণ এবং বিকাশের অধিকার আছে, সিম্বায়োসিস সভ্যতা বিপন্ন জাতির সংস্কৃতি রক্ষার জন্য বিশেষ তহবিল স্থাপন করে।</li><li><strong>শিক্ষা অধিকারের সমতা</strong>: প্রতিটি জাতির সদস্য সমান শিক্ষার অধিকার উপভোগ করে, শিক্ষা ব্যবস্থা বিভিন্ন জাতির শারীরবৃত্তীয় এবং সংজ্ঞামূলক বৈশিষ্ট্যগুলি যথেষ্ট বিবেচনা করে, পার্থক্যমূলক শিক্ষা প্রকল্প প্রদান করে।</li><li><strong>ক্ষতি অধিকারের সমতা</strong>: তিনশত সেট মূল ক্ষতি ব্যবস্থা সব জাতির জন্য সমানভাবে খোলা আছে, ক্ষতি সম্পদ বরাদ্দ বিভিন্ন জাতির শারীরিক পার্থক্য এবং শক্তি চাহিদা যথেষ্ট বিবেচনা করে।</li><li><strong>বিশেষ চাহিদা নিরাপত্তা</strong>: বিশেষ শারীরবৃত্তীয় চাহিদা আছে এমন জাতির জন্য (যেমন উপাদান জাতির শক্তি পরিবেশ চাহিদা, উদ্ভিদ জাতির আলোকচিত্র চাহিদা), সিম্বায়োসিস সভ্যতা পাবলিক সুবিধা এবং আবাসন পরিবেশে লক্ষ্যযুক্ত নিরাপত্তা প্রদান করে।</li></ol><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>সব জাতির নামতালিকা হলো অ্যাঙ্কর সিম্বায়োসিস সভ্যতার &quot;সব জাতি একসাথে অগ্রসর&quot; ধারণার নির্দিষ্ট উপস্থাপনা। মানব রূপ থেকে চেতনা রূপ পর্যন্ত, পদার্থ জীবন থেকে ডিজিটাল জীবন পর্যন্ত, প্রতিটি জাতি তার অনন্য অস্তিত্বের পদ্ধতির মাধ্যমে সিম্বায়োসিস সভ্যতায় অপ্রতিস্থাপনীয় শক্তি অবদান রাখে। সব জাতির প্রজাতন্ত্র মানে সব জাতিকে মানব জাতিতে একীভূত করা নয়, বরং বৈচিত্র্যকে সম্মান করার ভিত্তিতে সাধারণ বিবর্তন অর্জন করা—এটাই সিম্বায়োসিস সভ্যতার লুণ্ঠনশৈলী সভ্যতাকে অতিক্রম করার মূল কারণ।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>50-সব জাতির বংশতালিকার সারসংক্ষেপ</li><li>51-মানব জাতির অবস্থান এবং বৈশিষ্ট্য</li><li>77-সব জাতির প্রজাতন্ত্র প্রতিষ্ঠা</li></ul>',31)])])}const q=d(e,[["render",o]]);export{u as __pageData,q as default};
